mapper.select:
SELECT COUNT(*) 
FROM ENROLLMENT 
WHERE COURSE_ID = #{courseId}

SELECT M.NAME, NVL(D.DEPARTMENT_NAME, '미지정') AS DEPT_NAME, P.POSITION_NAME, TO_CHAR(C.END_DATE, 'YYYY-MM-DD') AS END_DATE, CASE C.STATUS WHEN 'W' THEN '예정' WHEN 'Y' THEN '진행중' WHEN 'N' THEN '종료' END AS STATUS_NAME, NVL(TRUNC( (SELECT COUNT(*) FROM CHAPTER_PROGRESS CP WHERE CP.ENROLLMENT_ID = E.ENROLLMENT_ID AND CP.IS_COMPLETED = 'Y') / (SELECT COUNT(*) FROM CHAPTER CH WHERE CH.COURSE_ID = E.COURSE_ID) * 100 ), 0) AS PROGRESS FROM ENROLLMENT E JOIN MEMBER M ON E.MEMBER_ID = M.MEMBER_ID LEFT JOIN DEPARTMENT D ON M.DEPARTMENT_ID = D.DEPARTMENT_ID LEFT JOIN POSITION P ON M.POSITION_ID = P.POSITION_ID JOIN COURSE C ON E.COURSE_ID = C.COURSE_ID WHERE E.COURSE_ID = #{courseId}
AND M.DEPARTMENT_ID = #{deptFilter}
ORDER BY
M.NAME PROGRESS DEPT_NAME P.POSITION_NAME E.ENROLLMENT_ID
ASC DESC
